            aWandererG = aWandererG ^ (((RotL64(aIngress, 10U) + RotL64(aOrbiterG, 46U)) + aOrbiterE) + aPhaseCWandererUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aPrevious, 19U) + RotL64(aOrbiterG, 35U)) + aOrbiterH);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 39U) + RotL64(aOrbiterI, 43U)) + aOrbiterE) + aNonceWordN);
            //
            aCarry = aCarry + (RotL64(aWandererA, 43U) ^ aWandererI);
