            //
            aOrbiterF = ((aOrbiterF + aOrbiterE) + 0x8445E3C407755120ULL) + aPhaseDOrbiterUpdateSaltE[((aIndex + 21U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x3765E9102D374A6EULL;
