            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x86C68E08F1F952F0ULL) + aPhaseDOrbiterUpdateSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0xD0C85278B7242E4BULL) ^ aNonceWordG;
            aOrbiterG = RotL64((aOrbiterG * 0xD495E9D21A88B4D9ULL), 35U);
