            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x6C56DCECD7C5DAE2ULL) ^ aPhaseDOrbiterUpdateSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
