            //
            aOrbiterH = (aWandererH + RotL64(aScatter, 11U)) + 0x8C7E591030A3C8BFULL;
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 19U)) + RotL64(aCarry, 3U)) + 0xA97957EEA5674CEEULL;
            aOrbiterG = (((aWandererI + RotL64(aIngress, 37U)) + RotL64(aCarry, 53U)) + 0x905435DCF5EA75C3ULL) + aPhaseCOrbiterAssignSaltB[((aIndex + 27U)) & S_SALT1];
