            aOrbiterJ = ((aWandererK + RotL64(aCross, 60U)) + 0x4E0981E4F443D2C5ULL) + aPhaseCOrbiterAssignSaltA[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterA = (aWandererE + RotL64(aScatter, 53U)) + 0x597DD9F17EEB9455ULL;
            //
