            aCross = (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 18145U)) & S_BLOCK1], 19U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 16624U)) & S_BLOCK1], 5U));
