            //
            aOrbiterE = (aWandererI + RotL64(aCross, 3U)) + 0x4A92CCDCD6346175ULL;
            aOrbiterG = (((aWandererD + RotL64(aIngress, 19U)) + RotL64(aCarry, 37U)) + 0x2D89DFB438A38A4EULL) + aPhaseCOrbiterAssignSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterB = ((aWandererG + RotL64(aScatter, 41U)) + RotL64(aCarry, 21U)) + 0xFEF58E6088EE8F04ULL;
            aOrbiterK = ((aWandererB + RotL64(aPrevious, 57U)) + RotL64(aCarry, 3U)) + 0xCEC781864A6CE0A4ULL;
            aOrbiterF = (aWandererE + RotL64(aIngress, 51U)) + 0x99E9D9552CD65BA9ULL;
            aOrbiterC = (aWandererF + RotL64(aCross, 35U)) + 0x662377AB462A6C2AULL;
            aOrbiterI = ((aWandererC + RotL64(aScatter, 28U)) + 0x6D5DFD5DC42E2E0EULL) + aPhaseCOrbiterAssignSaltB[(((31U - aIndex) + 20U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xAA7EF30B491449FDULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0xA3371434627D0C2CULL) ^ aPhaseCOrbiterUpdateSaltE[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x9F33D294F2D67CF5ULL), 21U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x410A8CEE9C31A6F0ULL) + aPhaseCOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
