            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x205AC94BADF21C76ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x8669E5C9836CD34FULL;
            aOrbiterF = RotL64((aOrbiterF * 0xA23D932D9A229563ULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x90C926036197644EULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x3E70CDDEA78DE4F0ULL;
