            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x3DDCA599EAAB0BC7ULL) + aPhaseCOrbiterUpdateSaltB[((aIndex + 3U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x51913CD04AB67C13ULL) ^ aPhaseCOrbiterUpdateSaltF[(((31U - aIndex) + 18U)) & S_SALT1];
