            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x235F12EA5277A77AULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x97CA8818725E86F0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC44C66DF86B80DC7ULL), 57U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterK, 35U);
